diff --git a/src/main/java/example/PingController.java b/src/main/java/example/PingController.java
new file mode 100644
--- /dev/null
+++ b/src/main/java/example/PingController.java
@@ -0,0 +1,11 @@
+@RestController
+final class PingController {
+    @GetMapping("/api/ping")
+    ResponseEntity<Map<String, String>> ping(Authentication authentication) {
+        if (authentication == null) {
+            return ResponseEntity.status(401).build();
+        }
+        return ResponseEntity.ok(Map.of("status", "ok"));
+    }
+}

